// One item per repository, so a repo you cannot read costs that repo and not
// the run.
//
// single-item input: the settings row.
const cfg = $('Settings').first().json;
const raw = String(cfg.repos || '');

const seen = new Set();
const out = [];
for (const part of raw.split(/[,\n;]+/)) {
  const t = part.trim()
    .replace(/^https?:\/\/(www\.)?github\.com\//i, '')
    .replace(/\.git$/i, '')
    .replace(/\/+$/, '');
  if (!t) { continue; }
  const bits = t.split('/').filter(Boolean);
  if (bits.length < 2) {
    throw new Error('Settings.repos wants owner/name, got "' + part.trim() + '".');
  }
  const key = (bits[0] + '/' + bits[1]).toLowerCase();
  if (seen.has(key)) { continue; }
  seen.add(key);
  out.push({ json: {
    owner: bits[0],
    repo: bits[1],
    slug: bits[0] + '/' + bits[1],
    // `since` filters on *updated*, which is the only window the API offers.
    // It is deliberately wider than the reporting window: a pull request merged
    // inside the window but not touched since would otherwise be missed.
    since: new Date(Date.now() - (Number(cfg.days) + 14) * 86400000).toISOString(),
  }});
}

if (!out.length) {
  throw new Error('No repositories in Settings. Put at least one owner/name in the repos field.');
}
return out;

// Closed is not shipped.
//
// Measured on one page of twenty closed pull requests from a real repository:
// eleven of them had never been merged. `state=closed` includes everything that
// was rejected, and `merged_at` is the only field that says otherwise.
//
// The window is applied here rather than to the API's ordering, because GitHub
// cannot sort by merge date. Sorting by `updated` put a pull request merged on
// 2026-05-22 in the middle of a page of 31 August merges, because somebody had
// commented on it.
const cfg = $('Settings').first().json;
const days = Math.max(1, Number(cfg.days) || 7);
const cutoff = Date.now() - days * 86400000;

const repos = $('List Your Repos').all().map(function (i) { return i.json; });
const rows = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const pr = j.pull_request;
  if (!pr || !pr.merged_at) { continue; }
  const mergedAt = Date.parse(pr.merged_at);
  if (!mergedAt || mergedAt < cutoff) { continue; }

  // The GitHub node returns the issues of every repo in one stream, and an
  // issue does not carry its repository. The URL does.
  const from = String(j.html_url || '').match(/github\.com\/([^\/]+\/[^\/]+)\//);
  const slug = from ? from[1] : (repos.length === 1 ? repos[0].slug : 'unknown');

  rows.push({
    pr_key: slug + '#' + j.number,
    repo: slug,
    number: j.number,
    title: String(j.title || '').trim(),
    body: String(j.body || '').replace(/<!--[\s\S]*?-->/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 700),
    author: String((j.user || {}).login || ''),
    labels: (j.labels || []).map(function (l) { return String(l.name || l); }),
    url: String(j.html_url || ''),
    merged_on: String(pr.merged_at).slice(0, 10),
  });
}

if (!rows.length) {
  return [{ json: { pr_key: '', title: '', nothing: true } }];
}
return rows.map(function (r) { return { json: r }; });

// Everything a customer could not see even if they were looking.
//
// Bots first: eight of twenty pull requests on that page were `n8n-cat-bot[bot]`
// and `n8n-assistant[bot]`, with titles like "chore: Update e2e impact map".
// Then the conventional-commit prefixes that are invisible by definition. The
// prefix is free signal and every single title on that page carried one.
const cfg = $('Settings').first().json;

const prefixes = String(cfg.skip_prefixes || '')
  .split(',').map(function (p) { return p.trim().toLowerCase(); }).filter(Boolean);
const skipLabels = String(cfg.skip_labels || '')
  .split(',').map(function (p) { return p.trim().toLowerCase(); }).filter(Boolean);
const keepBots = cfg.include_bots === true;

const kept = [];
let bots = 0;
let internal = 0;

for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.pr_key) { continue; }

  if (!keepBots && (/\[bot\]$/i.test(r.author) || /^(dependabot|renovate|github-actions)/i.test(r.author))) {
    bots++;
    continue;
  }

  const prefix = (String(r.title).match(/^([a-z]+)(\([^)]*\))?!?:/i) || [])[1];
  if (prefix && prefixes.indexOf(prefix.toLowerCase()) >= 0) {
    internal++;
    continue;
  }

  const labels = (r.labels || []).map(function (l) { return String(l).toLowerCase(); });
  if (labels.some(function (l) { return skipLabels.indexOf(l) >= 0; })) {
    internal++;
    continue;
  }

  kept.push(Object.assign({}, r, { prefix: prefix ? prefix.toLowerCase() : '' }));
}

// Never zero items: the counts have to reach the digest and the quiet branch has
// to stay reachable.
return [{ json: {
  candidates: kept,
  merged_total: $input.all().filter(function (i) { return (i.json || {}).pr_key; }).length,
  bots_dropped: bots,
  internal_dropped: internal,
}}];

// What has not been written about yet.
//
// Without this, a pull request merged on Friday is in next Friday's changelog
// too, because the window is a window and not a bookmark.
//
// single-item input: the step above folds the run into one item.
const s = $('Drop What Nobody Can See').first().json;

const seen = new Set();
for (const row of $('Read What You Already Shipped').all()) {
  const j = row.json || {};
  if (j.pr_key) { seen.add(String(j.pr_key)); }
}

// Capped, because everything below goes into one prompt and comes back as one
// JSON array. A hundred changes in means an answer long enough to be cut off,
// and a cut-off answer is an empty changelog.
const cap = Math.max(1, Number($('Settings').first().json.max_changes) || 25);
const fresh = (s.candidates || [])
  .filter(function (c) { return !seen.has(c.pr_key); })
  .slice(0, cap);

const block = fresh.map(function (c, i) {
  return (i + 1) + '. [' + c.repo + ' #' + c.number + ', merged ' + c.merged_on + ']\n' +
    '   ' + c.title + '\n' +
    (c.body ? '   ' + c.body.slice(0, 400) + '\n' : '');
}).join('\n');

return [{ json: {
  has_candidates: fresh.length > 0,
  fresh: fresh,
  fresh_count: fresh.length,
  block: block,
  merged_total: s.merged_total,
  bots_dropped: s.bots_dropped,
  internal_dropped: s.internal_dropped,
}}];

parameters.text:
=You are deciding which merged pull requests a customer of this product would notice. Most of them would not.

CHANGES
{{ $json.block }}

For each numbered change, answer "yes" only when somebody who uses the product but never reads the repository would be able to tell the difference: a new capability, a behaviour that changed, a bug they could have hit, a limit that moved, something that got visibly faster.

Answer "no" for refactors, test coverage, internal tooling, dependency bumps, documentation for contributors, and anything whose effect stops at the codebase. Answer "no" when the title is too vague to tell - a change nobody can describe is not one to announce.

Return JSON only: {"changes": [{"number": 1, "visible": "yes" or "no", "note": "what the customer would notice, in one clause"}]}

