// Which of them a customer would notice.
//
// The enum comes back off its list often enough to plan for - "Yes", "maybe"
// and "partially" have all appeared where one of two words was asked for - so
// anything that is not exactly yes counts as no.
//
// single-item input: one call covers the whole list.
const shortlist = $('Only What Is New').first().json;
const raw = String(($input.first().json || {}).text || '');

let parsed = {};
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s >= 0 && e > s) {
  try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch (err) { parsed = {}; }
}

// A truncated answer is the dangerous failure here: JSON.parse fails, every
// verdict falls back to "no", and the workflow reports that nothing shipped -
// quietly, in the safe-looking direction. Seen live: the model answered
// correctly about all 23 changes and the reply was cut off mid-array, so the
// changelog came out empty and green.
if (shortlist.fresh.length && !(parsed.changes || []).length) {
  throw new Error(
    'The answer from the model could not be read as JSON. It is usually cut off - ' +
    'raise max tokens on the model node, or lower max_changes in Settings. ' +
    'The last 200 characters were: ' + raw.slice(-200)
  );
}

const calls = new Map();
for (const row of (parsed.changes || [])) {
  const n = Number(row && row.number);
  if (n >= 1 && n <= shortlist.fresh.length) {
    calls.set(n, {
      visible: String((row && row.visible) || '').toLowerCase().trim() === 'yes',
      note: String((row && row.note) || '').slice(0, 200),
    });
  }
}

const judged = shortlist.fresh.map(function (c, i) {
  const v = calls.get(i + 1) || { visible: false, note: 'The model said nothing about this one.' };
  return Object.assign({}, c, { visible: v.visible, note: v.note });
});

const worth = judged.filter(function (c) { return c.visible; });

const block = worth.map(function (c, i) {
  return (i + 1) + '. ' + c.title + '  (' + c.repo + ' #' + c.number + ')\n' +
    '   ' + (c.body || '').slice(0, 400) + '\n   why it matters: ' + c.note;
}).join('\n\n');

return [{ json: {
  judged: judged,
  worth: worth,
  worth_count: worth.length,
  has_worth: worth.length > 0,
  block: block,
}}];

// The changelog, with the arithmetic that produced it.
//
// The counts belong in the email. "Forty-one merged, nine worth telling you
// about" is the sentence that makes the nine believable.
//
// single-item input: one call wrote the whole note.
const found = $('Only What Is New').first().json;
const judged = $('Read The Verdicts').first().json;
const raw = String(($input.first().json || {}).text || '').trim();

const note = raw.replace(/^```[a-z]*\n?/i, '').replace(/```$/, '').trim();

const summary = [
  found.merged_total + ' pull requests merged in the window.',
  found.bots_dropped ? found.bots_dropped + ' were bots.' : '',
  found.internal_dropped ? found.internal_dropped + ' were internal by prefix or label.' : '',
  judged.worth_count + ' of the remaining ' + found.fresh_count + ' are things a customer would notice.',
].filter(Boolean).join(' ');

const body = note + '\n\n---\n' + summary + '\n\nEvery change considered:\n' +
  judged.judged.map(function (c) {
    return (c.visible ? '  * ' : '  - ') + c.repo + ' #' + c.number + ' ' + c.title;
  }).join('\n');

return [{ json: {
  subject: 'Changelog draft - ' + judged.worth_count + ' change' + (judged.worth_count === 1 ? '' : 's') + ' worth announcing',
  body: body,
  worth_count: judged.worth_count,
}}];

// One row per pull request judged, whichever way it went. Storing only the
// visible ones means the invisible ones are judged again every week for ever.
//
// single-item input: the judging step folds the run into one item.
const judged = $('Read The Verdicts').first().json;
const today = new Date().toISOString().slice(0, 10);
return (judged.judged || []).map(function (c) {
  return { json: {
    pr_key: c.pr_key,
    repo: c.repo,
    number: c.number,
    title: String(c.title || '').slice(0, 200),
    verdict: c.visible ? 'announced' : 'internal',
    merged_on: c.merged_on || today,
  }};
});
